-- Venue Live Guest "Wedding Jepang Bersalju". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara jepang), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'jepang', 'Wedding Jepang Bersalju', 'jepang', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 148, 'center 38%',
  $t${"name":"Jepang Bersalju","orn":"diamond","ui":{"ivory":"#FAF4F4","white":"#FFFFFF","soft":"#EBDDE0","soft2":"#C9A24A","accent":"#B3262E","deep":"#4A1A24","ink":"#4A1A24","mute":"#8F7480","line":"#E6D3D8","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F6EDEE","ink":"#4A1A24","accent":"#B3262E","gold":"#C9A24A","leaf":"#EBDDE0","hbg":"rgba(250,244,244,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(74,26,36,.9)","acc":"#F2C94C","on":"#4A1A24"},"scr":{"wine":"#4A1A24","veil":"250,244,244"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'jepang');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/jepang/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/jepang/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/jepang/stall_snacks.webp","w":2.8},"stall_candy":{"url":"/assets/live-decor/jepang/stall_candy.webp","w":8.6,"x":-14.5,"z":4.5},"stall_drinks":{"url":"/assets/live-decor/jepang/stall_drinks.webp","w":10.2,"x":-9.4,"z":-11.5},"photobooth":{"url":"/assets/live-decor/jepang/photobooth.webp","w":6.4},"claw":{"url":"/assets/live-decor/jepang/claw.webp","w":9.0},"arch":{"url":"/assets/live-decor/jepang/arch.webp"},"fountain":{"url":"/assets/live-decor/jepang/fountain.webp","w":7.6,"x":9.3,"z":-15.5},"sign":{"url":"/assets/live-decor/jepang/sign.webp","w":1.5,"x":-5.6,"z":9},"easel":{"url":"/assets/live-decor/jepang/easel.webp","w":4.4,"x":5.2,"z":10.0},"table":{"url":"/assets/live-decor/jepang/table.webp","w":3.6,"x":-8.8,"z":3.6},"banner":{"url":"/assets/live-decor/jepang/banner.webp","w":1.5,"x":9.6,"z":8.8},"gifts":{"url":"/assets/live-decor/jepang/gifts.webp","w":2.4},"lamp":{"url":"/assets/live-decor/jepang/lamp.webp","w":1.4,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/jepang/rope.webp","w":2.0,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/jepang/planter.webp","w":1.4,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/jepang/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/jepang/av_host.webp","name":"Pengantin"},"av_l1":{"url":"/assets/live-decor/jepang/av_l1.webp","name":"Kak Haori Navy"},"av_l2":{"url":"/assets/live-decor/jepang/av_l2.webp","name":"Kak Syal Merah"},"av_l3":{"url":"/assets/live-decor/jepang/av_l3.webp","name":"Kak Hakama Fuji"},"av_p1":{"url":"/assets/live-decor/jepang/av_p1.webp","name":"Kak Kimono Pink"},"av_p2":{"url":"/assets/live-decor/jepang/av_p2.webp","name":"Kak Hijab Lilac"},"av_p3":{"url":"/assets/live-decor/jepang/av_p3.webp","name":"Kak Kimono Biru"}}$d$::jsonb, background_url = '/assets/live-decor/jepang/painting.webp', active = true, updated_at = now() where key = 'jepang';
